function parseWindow(startText, endText, label, errors) {
  const s = String(startText).match(HHMM_RE);
  const e = String(endText).match(HHMM_RE);
  if (!s || !e) {
    errors.push(`${label} window must use HH:MM (24h), got "${startText}"-"${endText}"`);
