const HHMM_RE = /^([01]\d|2[0-3]):([0-5]\d)$/;

const RESOLUTION_SOURCES = ['explicit', 'ip', 'region', 'phone', 'country'];

function isUnconfigured(value) {
  if (value === undefined || value === null) return true;
