      maxDelayHours: readIntEnv(env.MAX_DELAY_HOURS, 96, { min: 1, max: 336 }),
      maxWaitCycles: readIntEnv(env.MAX_WAIT_CYCLES, 3, { min: 1, max: 10 }),
    },
    dispatch: {
