// ---- src/core/timezone-validator.js ----
/**
 * Timezone resolution and outbound-window evaluation.
 *
 * Resolution signals (tried in RESOLUTION_ORDER, default explicit → region → phone → country → ip):
 *   explicit  a timezone on the payload or HubSpot's hs_timezone (IANA or HubSpot's "america_slash_new_york" form)
 *   ip        IP_TIMEZONE_PROVIDER (edge header or ipinfo), or HubSpot's hs_ip_timezone
 *   region    country + state/province (US, CA, AU), split regions keep every zone they span
 *   phone     E.164 calling code; NANP area codes for the Caribbean, Hawaii and Alaska
 *   country   the country property alone
 *
 * Multi-zone results stay multi-zone: the window must be open in every candidate zone.
 * With CONFLICT_POLICY=conservative, a second signal that disagrees by more than
 * CONFLICT_THRESHOLD_HOURS from every primary zone is merged in as well (VPNs, travel, ported
 * numbers). An explicit timezone is authoritative and never widened.
 *
 * All maths uses Intl, so DST transitions follow the runtime's tz database.
 */

const WEEKDAY_INDEX = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
const MINUTE_MS = 60000;

function canonicalTimeZone(value) {
  if (value === undefined || value === null) return null;
  let raw = String(value).trim();
  if (!raw) return null;
  raw = raw.replace(/_slash_/gi, '/').replace(/_underscore_/gi, '_');
  if (!raw.includes('/') && !/^utc$|^gmt$/i.test(raw)) return null;
  if (!isValidTimeZone(raw)) return null;
  return new Intl.DateTimeFormat('en-US', { timeZone: raw }).resolvedOptions().timeZone;
}

function normalizeCountryCode(value) {
  if (value === undefined || value === null) return null;
  const v = String(value).trim();
  if (!v) return null;
  if (/^[A-Za-z]{2}$/.test(v)) {
    const iso = v.toUpperCase();
    const known = SINGLE_ZONE_COUNTRIES[iso] || MULTI_ZONE_COUNTRIES[iso];
    return known ? (iso === 'UK' ? 'GB' : iso) : iso === 'UK' ? 'GB' : null;
  }
  return COUNTRY_NAME_ALIASES[v.toLowerCase()] || null;
}

function zonesForCountry(iso) {
  if (!iso) return [];
  if (MULTI_ZONE_COUNTRIES[iso]) return MULTI_ZONE_COUNTRIES[iso].slice();
  return SINGLE_ZONE_COUNTRIES[iso] ? [SINGLE_ZONE_COUNTRIES[iso]] : [];
}

function zonesForRegion(iso, region) {
  if (!iso || !region || !REGION_ZONES[iso]) return [];
  const raw = String(region).trim();
  const code = REGION_ZONES[iso][raw.toUpperCase()] ? raw.toUpperCase() : (REGION_NAME_ALIASES[iso] || {})[raw.toLowerCase()];
  return code && REGION_ZONES[iso][code] ? REGION_ZONES[iso][code].slice() : [];
}

/** Parses +CC / 00CC numbers (or national numbers with DEFAULT_PHONE_COUNTRY) into a country and zones. */
function resolvePhone(rawPhone, defaultCountry = '') {
  if (!rawPhone) return null;
  const text = String(rawPhone).trim();
  let digits = text.replace(/[^\d+]/g, '');
  let international = false;
  if (digits.startsWith('+')) {
    international = true;
    digits = digits.slice(1).replace(/\+/g, '');
  } else if (digits.startsWith('00')) {
    international = true;
    digits = digits.slice(2);
  }
  digits = digits.replace(/\D/g, '');
  if (digits.length < 7 || digits.length > 15) return null;
  let callingCode = null;
  let country = null;
  if (international) {
    for (const len of [1, 2, 3]) {
      const code = Number(digits.slice(0, len));
      if (CALLING_CODES[code]) {
        callingCode = code;
        country = CALLING_CODES[code];
        break;
      }
    }
    if (!country) return null;
  } else if (defaultCountry) {
    country = defaultCountry === 'US' || defaultCountry === 'CA' ? 'NANP' : defaultCountry;
    callingCode = country === 'NANP' ? 1 : null;
    if (country === 'NANP') digits = digits.length === 10 ? `1${digits}` : digits;
  } else {
    return null;
  }
  if (country === 'NANP') {
    const area = Number(digits.slice(1, 4));
    if (digits.length !== 11) return null;
    if (NANP_SPECIAL_AREA_CODES[area]) return { callingCode: 1, country: 'NANP', areaCode: area, zones: [NANP_SPECIAL_AREA_CODES[area]], precision: 'area_code' };
    return { callingCode: 1, country: 'NANP', areaCode: area, zones: NANP_MAINLAND_ZONES.slice(), precision: 'nanp_mainland' };
  }
  const zones = zonesForCountry(country);
  return zones.length ? { callingCode, country, zones, precision: zones.length === 1 ? 'country' : 'country_multi_zone' } : null;
}

function localParts(ms, zone) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zone,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    weekday: 'short',
  }).formatToParts(new Date(ms));
  const get = (type) => parts.find((p) => p.type === type).value;
  const hour = Number(get('hour')) % 24;
  return {
    date: `${get('year')}-${get('month')}-${get('day')}`,
    hour,
    minute: Number(get('minute')),
    minuteOfDay: hour * 60 + Number(get('minute')),
    weekday: WEEKDAY_INDEX[get('weekday')],
    label: `${get('weekday')} ${get('year')}-${get('month')}-${get('day')} ${String(hour).padStart(2, '0')}:${get('minute')}`,
  };
}

function utcOffsetMinutes(ms, zone) {
  const p = new Intl.DateTimeFormat('en-US', { timeZone: zone, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric' })
    .formatToParts(new Date(ms))
    .reduce((acc, part) => ({ ...acc, [part.type]: Number(part.value) }), {});
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour % 24, p.minute);
  return Math.round((asUtc - Math.floor(ms / MINUTE_MS) * MINUTE_MS) / MINUTE_MS);
}

/** Smallest UTC-offset distance between any zone in A and any zone in B, in hours. */
function offsetDistanceHours(zonesA, zonesB, ms) {
  let best = Infinity;
  for (const a of zonesA) {
    const oa = utcOffsetMinutes(ms, a);
    for (const b of zonesB) best = Math.min(best, Math.abs(oa - utcOffsetMinutes(ms, b)));
  }
  return best / 60;
}

/** Collects every usable signal for a lead. `lead` uses HubSpot property names. */
function collectTimezoneSignals(lead, { resolution }, ipTimezone = null) {
  const signals = {};
  const explicit = canonicalTimeZone(lead.timezone) || canonicalTimeZone(lead.hs_timezone);
  if (explicit) signals.explicit = { zones: [explicit], detail: lead.timezone ? 'payload timezone' : 'hs_timezone' };
  const ip = canonicalTimeZone(ipTimezone) || canonicalTimeZone(lead.hs_ip_timezone);
  if (ip) signals.ip = { zones: [ip], detail: ipTimezone ? `IP lookup (${resolution.ipProvider})` : 'hs_ip_timezone' };
  const country = normalizeCountryCode(lead.country) || normalizeCountryCode(lead.ip_country);
  const regionZones = zonesForRegion(country, lead.state);
  if (regionZones.length) signals.region = { zones: regionZones, detail: `${country}/${String(lead.state).trim()}` };
  const phone = resolvePhone(lead.phone, resolution.defaultPhoneCountry) || resolvePhone(lead.mobilephone, resolution.defaultPhoneCountry);
  if (phone) signals.phone = { zones: phone.zones, detail: `+${phone.callingCode} (${phone.precision})` };
  const countryZones = zonesForCountry(country);
  if (countryZones.length) signals.country = { zones: countryZones, detail: country };
  return { signals, country: country || (phone && phone.country !== 'NANP' ? phone.country : phone ? 'US' : null) };
}

function confidenceFor(source, zones) {
  if (source === 'explicit') return 'high';
  if (zones.length > 1) return 'low';
  if (source === 'region' || source === 'ip') return 'high';
  return 'medium';
}

function resolveTimezone(lead, config, { ipTimezone = null, nowMs = Date.now() } = {}) {
  const { signals, country } = collectTimezoneSignals(lead, config, ipTimezone);
  const available = config.resolution.order.filter((s) => signals[s]);
  if (!available.length) {
    if (config.resolution.unknownAction === 'default') {
      return { resolved: true, timezone: config.resolution.defaultTimezone, candidates: [config.resolution.defaultTimezone], source: 'default', confidence: 'none', country, signals, conflict: null };
    }
    return { resolved: false, timezone: null, candidates: [], source: null, confidence: 'none', country, signals, conflict: null };
  }
  const primary = available[0];
  let candidates = signals[primary].zones;
  let conflict = null;
  const secondary = primary === 'explicit' ? null : available.find((s) => s !== primary);
  if (secondary) {
    const distance = offsetDistanceHours(candidates, signals[secondary].zones, nowMs);
    if (distance > config.resolution.conflictThresholdHours) {
      conflict = { with: secondary, spreadHours: distance, policy: config.resolution.conflictPolicy };
      if (config.resolution.conflictPolicy === 'conservative') candidates = [...new Set([...candidates, ...signals[secondary].zones])];
    }
  }
  return {
    resolved: true,
    timezone: candidates[0],
    candidates,
    source: primary,
    confidence: conflict && config.resolution.conflictPolicy === 'conservative' ? 'low' : confidenceFor(primary, candidates),
    country,
    signals,
    conflict,
  };
}

function channelWindow(windows, channel) {
  const call = windows.call;
  const email = windows.email;
  if (channel === 'call') return { startMinute: call.startMinute, endMinute: call.endMinute };
  if (channel === 'email') return { startMinute: email.startMinute, endMinute: email.endMinute };
  return { startMinute: Math.max(call.startMinute, email.startMinute), endMinute: Math.min(call.endMinute, email.endMinute) };
}

function holidaysFor(windows, country) {
  return [...(windows.holidays['*'] || []), ...((country && windows.holidays[country]) || [])];
}

function isOpenInZone(ms, zone, { window, windows, country }) {
  const p = localParts(ms, zone);
  if (!windows.weekdays.includes(p.weekday)) return false;
  if (holidaysFor(windows, country).includes(p.date)) return false;
  return p.minuteOfDay >= window.startMinute && p.minuteOfDay < window.endMinute - windows.endBufferMinutes;
}

function stableHash(text) {
  let h = 2166136261;
  for (const ch of String(text)) {
    h ^= ch.codePointAt(0);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h;
}

/**
 * Decides whether the lead can be contacted now in every candidate zone, and if not,
 * when the earliest shared window opens (searched up to MAX_DELAY_HOURS ahead).
 */
function evaluateOutboundWindow({ candidates, channel, country, nowMs, windows, jitterKey = '' }) {
  const window = channelWindow(windows, channel);
  const ctx = { window, windows, country };
  const openAll = (ms) => candidates.every((zone) => isOpenInZone(ms, zone, ctx));
  const localTimes = Object.fromEntries(candidates.map((z) => [z, localParts(nowMs, z).label]));
  if (window.endMinute - windows.endBufferMinutes <= window.startMinute) {
    return { status: 'manual', reason: 'window_shorter_than_end_buffer', localTimes, window };
  }
  if (openAll(nowMs)) return { status: 'open', reason: 'inside_window', dispatchAt: new Date(nowMs).toISOString(), localTimes, window };
  const limit = nowMs + windows.maxDelayHours * 3600 * 1000;
  let t = Math.ceil((nowMs + 1) / MINUTE_MS) * MINUTE_MS;
  while (t % (5 * MINUTE_MS) !== 0 && t <= limit) {
    if (openAll(t)) break;
    t += MINUTE_MS;
  }
  if (!openAll(t)) {
    while (t <= limit && !openAll(t)) t += 5 * MINUTE_MS;
    if (t > limit) return { status: 'manual', reason: 'no_shared_window_within_max_delay', localTimes, window };
    for (let back = 1; back < 5 && openAll(t - MINUTE_MS); back += 1) t -= MINUTE_MS;
  }
  const opensAt = t;
  let dispatchAt = opensAt;
  if (windows.jitterMinutes > 0) {
    const jittered = opensAt + (stableHash(jitterKey) % (windows.jitterMinutes + 1)) * MINUTE_MS;
    if (openAll(jittered)) dispatchAt = jittered;
  }
  return {
    status: 'wait',
    reason: 'outside_window',
    opensAt: new Date(opensAt).toISOString(),
    dispatchAt: new Date(dispatchAt).toISOString(),
    delayMinutes: Math.round((dispatchAt - nowMs) / MINUTE_MS),
    localTimes,
    localTimesAtDispatch: Object.fromEntries(candidates.map((z) => [z, localParts(dispatchAt, z).label])),
    window,
  };
}

/** n8n-friendly single call: resolve + evaluate for one lead. */
function validateLeadTiming(lead, config, { nowMs = Date.now(), ipTimezone = null, channel } = {}) {
  const resolution = resolveTimezone(lead, config, { ipTimezone, nowMs });
  const effectiveChannel = ['call', 'email', 'both'].includes(channel) ? channel : config.windows.defaultChannel;
  if (!resolution.resolved) {
    return { resolution, channel: effectiveChannel, decision: { status: 'manual', reason: 'timezone_unresolved', localTimes: {} } };
  }
  const decision = evaluateOutboundWindow({
    candidates: resolution.candidates,
    channel: effectiveChannel,
    country: resolution.country,
    nowMs,
    windows: config.windows,
    jitterKey: lead.id || lead.email || '',
  });
  return { resolution, channel: effectiveChannel, decision };
}

// ---- src/core/dispatch.js ----
/**
 * HubSpot contact enrichment and write-back, optional IP timezone lookup, and the
 * dispatch hand-off (a signed HTTPS webhook to your sequencer, dialer or HubSpot workflow).
 *
 *   DRY_RUN=true      -> HubSpot PATCHes and dispatch webhooks are returned, never sent
 *   SANDBOX_MODE=true -> HubSpot writes require a SANDBOX / DEVELOPER_TEST portal (or
 *                        HUBSPOT_SANDBOX_PORTAL_ID); dispatch goes to DISPATCH_SANDBOX_WEBHOOK_URL only
 *   placeholder token -> offline: no HubSpot reads or writes
 */

const CONTACT_TIMING_PROPERTIES = ['email', 'phone', 'mobilephone', 'country', 'state', 'hs_timezone', 'hs_ip_timezone', 'ip_country'];

class DispatchGuardError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'DispatchGuardError';
    this.code = code;
  }
}

function createContactTimingClient({
  token,
  dryRun = true,
  sandboxMode = true,
  sandboxPortalId = '',
  baseUrl = 'https://api.hubapi.com',
  fetchImpl = globalThis.fetch,
  sleep = (ms) => new Promise((r) => setTimeout(r, ms)),
}) {
  const offline = isUnconfigured(token);
  const api = String(baseUrl).replace(/\/+$/, '');
  let sandboxVerdict = null;

  async function call(method, path, body, { allow404 = false } = {}) {
    if (offline) throw new DispatchGuardError('hubspot_offline', 'HubSpot token is a placeholder; live API calls are disabled');
    for (let attempt = 0; ; attempt += 1) {
      const response = await fetchImpl(`${api}${path}`, {
        method,
        headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
      if (response.status === 404 && allow404) return null;
      if ((response.status === 429 || response.status >= 500) && attempt < 3) {
        await sleep(Math.min(1000 * 2 ** attempt, 8000));
        continue;
      }
      const text = await response.text();
      if (!response.ok) throw new DispatchGuardError(`http_${response.status}`, `HubSpot ${method} ${path.split('?')[0]} failed with HTTP ${response.status}`);
      return text ? JSON.parse(text) : {};
    }
  }

  async function verifySandbox() {
    if (!sandboxVerdict) {
      sandboxVerdict = (async () => {
        const d = await call('GET', '/account-info/v3/details');
        const portalId = String(d && d.portalId !== undefined ? d.portalId : '');
        const accountType = String((d && d.accountType) || '').toUpperCase();
        if (!isUnconfigured(sandboxPortalId)) {
          if (portalId !== String(sandboxPortalId)) throw new DispatchGuardError('sandbox_portal_mismatch', 'SANDBOX_MODE=true but the token is not for HUBSPOT_SANDBOX_PORTAL_ID');
        } else if (!['SANDBOX', 'DEVELOPER_TEST'].includes(accountType)) {
          throw new DispatchGuardError('sandbox_account_required', `SANDBOX_MODE=true but the account type is "${accountType || 'unknown'}"`);
        }
        return true;
      })();
    }
    return sandboxVerdict;
  }

  async function getContact(contactId) {
    if (offline) return null;
    const r = await call('GET', `/crm/v3/objects/contacts/${encodeURIComponent(contactId)}?properties=${CONTACT_TIMING_PROPERTIES.join(',')}`, undefined, { allow404: true });
    return r ? { id: String(r.id), ...(r.properties || {}) } : null;
  }

  async function updateContact(contactId, properties) {
    if (!contactId) return { mode: 'skipped', reason: 'no_contact_id' };
    if (dryRun) return { mode: 'intercepted_dry_run', properties };
    if (offline) throw new DispatchGuardError('hubspot_offline', 'HubSpot token is a placeholder; live API calls are disabled');
    if (sandboxMode) await verifySandbox();
    await call('PATCH', `/crm/v3/objects/contacts/${encodeURIComponent(contactId)}`, { properties });
    return { mode: 'written', environment: sandboxMode ? 'sandbox' : 'production' };
  }

  return { offline, getContact, updateContact, verifySandbox };
}

/** Optional IP -> timezone. Never throws; returns null when unavailable. */
async function lookupIpTimezone({ ip, headers = {}, resolution, fetchImpl }) {
  if (resolution.ipProvider === 'header') {
    const entry = Object.entries(headers || {}).find(([k]) => k.toLowerCase() === resolution.ipTimezoneHeader);
    return entry ? String(Array.isArray(entry[1]) ? entry[1][0] : entry[1]).slice(0, 64) : null;
  }
  if (resolution.ipProvider === 'ipinfo' && ip && /^[0-9a-f.:]{3,45}$/i.test(String(ip))) {
    try {
      const response = await fetchImpl(`https://ipinfo.io/${encodeURIComponent(ip)}/json?token=${encodeURIComponent(resolution.ipinfoToken)}`, { method: 'GET', headers: { accept: 'application/json' } });
      if (!response.ok) return null;
      const body = JSON.parse(await response.text());
      return body && body.timezone ? String(body.timezone).slice(0, 64) : null;
    } catch {
      return null;
    }
  }
  return null;
}

function buildTimingProperties({ resolution, status, dispatchAt, reason }) {
  return {
    lead_local_timezone: resolution && resolution.timezone ? resolution.timezone : '',
    lead_timezone_candidates: resolution && resolution.candidates ? resolution.candidates.join(';').slice(0, 500) : '',
    lead_timezone_source: resolution && resolution.source ? resolution.source : 'unresolved',
    lead_timezone_confidence: resolution ? resolution.confidence : 'none',
    outbound_dispatch_status: status,
    outbound_dispatch_at: dispatchAt || '',
    outbound_dispatch_note: String(reason || '').slice(0, 250),
  };
}

/** Signed hand-off to the system that actually calls or emails. */
async function sendDispatchWebhook(payload, { config, fetchImpl }) {
  const target = config.sandboxMode ? config.dispatch.sandboxWebhookUrl : config.dispatch.webhookUrl;
  if (config.dryRun) return { mode: 'intercepted_dry_run', target: config.sandboxMode ? 'sandbox' : 'production' };
  if (isUnconfigured(target)) return { mode: 'not_configured' };
  if (!/^https:\/\//.test(target)) return { mode: 'refused_non_https' };
  const body = JSON.stringify(payload);
  const headers = { 'content-type': 'application/json' };
  if (!isUnconfigured(config.dispatch.webhookSecret)) {
    const ts = String(Math.floor(Date.now() / 1000));
    headers['x-signature-timestamp'] = ts;
    headers['x-signature'] = `sha256=${crypto.createHmac('sha256', config.dispatch.webhookSecret).update(`${ts}.${body}`).digest('hex')}`;
  }
  const response = await fetchImpl(target, { method: 'POST', headers, body });
  if (!response.ok) throw new DispatchGuardError(`dispatch_http_${response.status}`, `Dispatch webhook returned HTTP ${response.status}`);
  return { mode: 'sent', environment: config.sandboxMode ? 'sandbox' : 'production' };
}

// ---- src/core/pipeline.js ----
/**
 * Stages shared by the Node.js mirror and the n8n workflow.
 *
 *   intake -> enrich -> evaluate -> open    -> dispatch
 *                                -> wait    -> schedule -> (n8n Wait node) -> recheck -> open | wait | manual
 *                                -> manual  -> manual review
 *
 * Every stage takes and returns JSON-serializable data. HubSpot and dispatch calls
 * throw on failure so n8n can route the node's error output.
 */

function createDispatchClients(config, { fetchImpl, sleep } = {}) {
  return {
    crm: createContactTimingClient({
      token: config.hubspot.token,
      dryRun: config.dryRun,
      sandboxMode: config.sandboxMode,
      sandboxPortalId: config.hubspot.sandboxPortalId,
      baseUrl: config.hubspot.baseUrl,
      fetchImpl,
      ...(sleep ? { sleep } : {}),
    }),
  };
}

function headerValue(headers, name) {
  for (const [k, v] of Object.entries(headers || {})) if (k.toLowerCase() === name) return Array.isArray(v) ? v[0] : v;
  return null;
}

function secretMatches(given, expected) {
  const a = Buffer.from(String(given || ''));
  const b = Buffer.from(String(expected || ''));
  return a.length === b.length && a.length > 0 && crypto.timingSafeEqual(a, b);
}

const LEAD_FIELDS = ['email', 'phone', 'mobilephone', 'country', 'state', 'timezone', 'hs_timezone', 'hs_ip_timezone', 'ip_country'];

/** Accepts a flat lead, a HubSpot workflow webhook ({ objectId, properties: { x: { value } } }) or { contactId, ... }. */
function extractLead(body) {
  const src = body && typeof body === 'object' && !Array.isArray(body) ? body : {};
  const props = src.properties && typeof src.properties === 'object' ? src.properties : {};
  const value = (k) => {
    const v = src[k] !== undefined ? src[k] : props[k];
    return v && typeof v === 'object' && 'value' in v ? v.value : v;
  };
  const idRaw = src.contactId ?? src.objectId ?? src.vid ?? value('hs_object_id');
  const lead = {};
  for (const f of LEAD_FIELDS) {
    const v = value(f);
    if (v !== undefined && v !== null && String(v).trim() !== '') lead[f] = String(v).trim().slice(0, 200);
  }
  return {
    contactId: idRaw !== undefined && /^\d{1,20}$/.test(String(idRaw)) ? String(idRaw) : null,
    lead,
    ip: typeof src.ip === 'string' ? src.ip.trim().slice(0, 45) : null,
    channel: ['call', 'email', 'both'].includes(String(src.channel || '').toLowerCase()) ? String(src.channel).toLowerCase() : null,
  };
}

function intakeStage({ body, headers = {} }, { config, now = Date.now() }) {
  const base = { receivedAt: new Date(now).toISOString(), dryRun: config.dryRun, sandboxMode: config.sandboxMode, waitCycle: 0 };
  const { errors, warnings } = validateDispatchConfig(config);
  if (errors.length) return { ...base, status: 'rejected', httpStatus: 500, reason: 'config_invalid', errors };
  if (Buffer.byteLength(JSON.stringify(body ?? {}), 'utf8') > config.webhook.maxBodyBytes) return { ...base, status: 'rejected', httpStatus: 413, reason: 'payload_too_large' };
  if (!isUnconfigured(config.webhook.secret) && !secretMatches(headerValue(headers, config.webhook.secretHeader), config.webhook.secret)) {
    return { ...base, status: 'rejected', httpStatus: 401, reason: 'invalid_webhook_secret' };
  }
  const { contactId, lead, ip, channel } = extractLead(body);
  if (!contactId && !Object.keys(lead).length) return { ...base, status: 'rejected', httpStatus: 422, reason: 'no_lead_data' };
  return { ...base, status: 'accepted', httpStatus: 202, reason: null, contactId, lead, ip, channel, edgeTimezone: headerValue(headers, config.resolution.ipTimezoneHeader), warnings };
}

async function enrichStage(ctx, { config, crm, fetchImpl }) {
  if (ctx.status !== 'accepted') return ctx;
  let lead = { ...ctx.lead };
  let crmFound = null;
  if (ctx.contactId && !crm.offline) {
    const contact = await crm.getContact(ctx.contactId);
    crmFound = Boolean(contact);
    if (contact) {
      for (const f of LEAD_FIELDS) if (contact[f] && f !== 'timezone') lead[f] = String(contact[f]);
      if (ctx.lead.timezone) lead.timezone = ctx.lead.timezone;
    }
  }
  const headers = ctx.edgeTimezone ? { [config.resolution.ipTimezoneHeader]: ctx.edgeTimezone } : {};
  const ipTimezone = await lookupIpTimezone({ ip: ctx.ip, headers, resolution: config.resolution, fetchImpl });
  const { email, ...withoutEmail } = lead;
  const { ip, edgeTimezone, ...rest } = ctx;
  return {
    ...rest,
    status: 'enriched',
    crmFound,
    ipTimezone,
    lead: { id: ctx.contactId || '', ...withoutEmail, ...(config.dispatch.includeEmail && email ? { email } : {}) },
    jitterKey: ctx.contactId || email || '',
  };
}

function evaluateStage(ctx, { config, now = Date.now() }) {
  if (ctx.status !== 'enriched' && ctx.status !== 'scheduled') return ctx;
  const { resolution, channel, decision } = validateLeadTiming({ ...ctx.lead, id: ctx.jitterKey }, config, { nowMs: now, ipTimezone: ctx.ipTimezone, channel: ctx.channel });
  const slim = {
    timezone: resolution.timezone,
    candidates: resolution.candidates,
    source: resolution.source,
    confidence: resolution.confidence,
    country: resolution.country,
    conflict: resolution.conflict,
    signals: Object.fromEntries(Object.entries(resolution.signals).map(([k, s]) => [k, { zones: s.zones, detail: s.detail }])),
  };
  let status = decision.status;
  let reason = decision.reason;
  if (status === 'wait' && ctx.waitCycle >= config.windows.maxWaitCycles) {
    status = 'manual';
    reason = 'max_wait_cycles_reached';
  }
  return { ...ctx, status, reason, channel, resolution: slim, decision, evaluatedAt: new Date(now).toISOString() };
}

async function scheduleStage(ctx, { config, crm }) {
  if (ctx.status !== 'wait') return ctx;
  const crmResult = config.hubspot.writeProperties
    ? await crm.updateContact(ctx.contactId, buildTimingProperties({ resolution: ctx.resolution, status: 'scheduled', dispatchAt: ctx.decision.dispatchAt, reason: `waiting for ${ctx.channel} window` }))
    : { mode: 'disabled' };
  return { ...ctx, status: 'scheduled', resumeAt: ctx.decision.dispatchAt, waitCycle: ctx.waitCycle + 1, crm: { schedule: crmResult.mode } };
}

async function dispatchStage(ctx, { config, crm, fetchImpl, now = Date.now() }) {
  if (ctx.status !== 'open') return ctx;
  const dispatchedAt = new Date(now).toISOString();
  const crmResult = config.hubspot.writeProperties
    ? await crm.updateContact(ctx.contactId, buildTimingProperties({ resolution: ctx.resolution, status: 'dispatched', dispatchAt: dispatchedAt, reason: `${ctx.channel} window open` }))
    : { mode: 'disabled' };
  const payload = {
    type: 'lead_dispatch_ready',
    contactId: ctx.contactId,
    ...(ctx.lead.email ? { email: ctx.lead.email } : {}),
    channel: ctx.channel,
    timezone: ctx.resolution.timezone,
    candidates: ctx.resolution.candidates,
    confidence: ctx.resolution.confidence,
    localTimes: ctx.decision.localTimes,
    dispatchedAt,
    dryRun: config.dryRun,
    sandboxMode: config.sandboxMode,
  };
  const webhook = await sendDispatchWebhook(payload, { config, fetchImpl });
  return { ...ctx, status: 'dispatched', dispatchedAt, crm: { ...(ctx.crm || {}), dispatch: crmResult.mode }, dispatchWebhook: webhook.mode };
}

async function manualReviewStage(ctx, { config, crm }) {
  if (ctx.status !== 'manual') return ctx;
  const crmResult = config.hubspot.writeProperties
    ? await crm.updateContact(ctx.contactId, buildTimingProperties({ resolution: ctx.resolution, status: 'manual_review', dispatchAt: '', reason: ctx.reason }))
    : { mode: 'disabled' };
  return { ...ctx, status: 'manual_review', crm: { ...(ctx.crm || {}), manual: crmResult.mode } };
}

function summarizeLead(ctx) {
  return {
    status: ctx.status,
    reason: ctx.reason || null,
    contactId: ctx.contactId || null,
    channel: ctx.channel || null,
    timezone: ctx.resolution ? ctx.resolution.timezone : null,
    candidates: ctx.resolution ? ctx.resolution.candidates : [],
    source: ctx.resolution ? ctx.resolution.source : null,
    confidence: ctx.resolution ? ctx.resolution.confidence : null,
    conflict: ctx.resolution ? ctx.resolution.conflict : null,
    localTimes: ctx.decision ? ctx.decision.localTimes : {},
    resumeAt: ctx.resumeAt || null,
    dispatchedAt: ctx.dispatchedAt || null,
    waitCycle: ctx.waitCycle || 0,
    crm: ctx.crm || null,
    dispatchWebhook: ctx.dispatchWebhook || null,
    dryRun: ctx.dryRun,
    sandboxMode: ctx.sandboxMode,
    errors: ctx.errors || [],
  };
}

/** One pass for the Node.js mirror. A "scheduled" result must be re-run with recheckLead at resumeAt. */
async function processLead(input, { config, fetchImpl = globalThis.fetch, clients, now = () => Date.now() }) {
  const { crm } = clients || createDispatchClients(config, { fetchImpl });
  let ctx = intakeStage(input, { config, now: now() });
  if (ctx.status !== 'accepted') return ctx;
  ctx = await enrichStage(ctx, { config, crm, fetchImpl });
  ctx = evaluateStage(ctx, { config, now: now() });
  return routeEvaluated(ctx, { config, crm, fetchImpl, now });
}

async function recheckLead(ctx, { config, fetchImpl = globalThis.fetch, clients, now = () => Date.now() }) {
  const { crm } = clients || createDispatchClients(config, { fetchImpl });
  const evaluated = evaluateStage(ctx, { config, now: now() });
  return routeEvaluated(evaluated, { config, crm, fetchImpl, now });
}

async function routeEvaluated(ctx, { config, crm, fetchImpl, now }) {
  if (ctx.status === 'open') return dispatchStage(ctx, { config, crm, fetchImpl, now: now() });
  if (ctx.status === 'wait') return scheduleStage(ctx, { config, crm });
  if (ctx.status === 'manual') return manualReviewStage(ctx, { config, crm });
  return ctx;
}

// ---- n8n stage runner ----
const env = $env;
const config = loadDispatchConfig(env);
const n8nHelpers = this.helpers;
const n8nSleep = (ms) => new Promise((resolve) => (typeof setTimeout === 'function' ? setTimeout(resolve, ms) : resolve()));
const n8nFetch = async (url, init = {}) => {
  const response = await n8nHelpers.httpRequest({
    url,
    method: init.method || 'GET',
    headers: init.headers || {},
    body: init.body,
    json: false,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 15000,
  });
  const raw = response.body;
  const text = typeof raw === 'string' ? raw : Buffer.isBuffer(raw) ? raw.toString('utf8') : raw == null ? '' : JSON.stringify(raw);
  return {
    ok: response.statusCode >= 200 && response.statusCode < 300,
    status: response.statusCode,
    headers: { get: (name) => (response.headers || {})[String(name).toLowerCase()] ?? null },
    text: async () => text,
    json: async () => JSON.parse(text),
  };
};
const clients = createDispatchClients(config, { fetchImpl: n8nFetch, sleep: n8nSleep });

const items = $input.all();
const failure = { status: 'failed', failures: items.length, errors: items.map((i) => String((i.json && (i.json.error && (i.json.error.message || i.json.error))) || 'unknown').slice(0, 300)), dryRun: config.dryRun, sandboxMode: config.sandboxMode, at: new Date().toISOString() };
return [{ json: failure }];
